entries[320659] = { ["name"] = "Niyas Werkzeuge: Kletten", ["text"] = "Seelenbandefähigkeit\nCa. 1.75 Procs pro Minute\nEure Schaden verursachenden Angriffe und Zauber haben eine Chance, Niyas Stachelkletten unter Euer Ziel zu werfen. Die Kletten bleiben am ersten Gegner haften, der sie durchschreitet, verringern seine Bewegungsgeschwindigkeit um 20% und fügen ihm im Verlauf von 6 Sek. [(Angriffskraft * 0.3312 * (1 + Vielseitigkeit)) * 6] Naturschaden zu." }
entries[320660] = { ["name"] = "Niyas Werkzeuge: Gift", ["text"] = "Seelenbandefähigkeit\nEure Unterbrechungen wenden Niyas betäubendes Gift auf Euer Ziel an, was ihm im Verlauf von 30 Sek. [(Angriffskraft * 0.05 * (1 + Vielseitigkeit)) * 30] Naturschaden zufügt. Mit Niyas betäubendem Gift belegte Ziele erleiden bei einer erneuten Unterbrechung zusätzlich [Angriffskraft * 0.24 * (1 + Vielseitigkeit)] Naturschaden." }
entries[320661] = { ["name"] = "Ansturm", ["text"] = "Unbegrenzte Reichweite\nSofort\nSobald Xav 100 Energie erreicht hat, zwingt er Spielercharaktere in die Duellgrube hinab. Der Sieger des Duells erhält ' Verherrlicht ', der Verlierer erleidet ' Blutig geschlagen '.\n\nSpielercharaktere erhalten alle 1 Sek. einen Stapel von ' Ruhmreicher Kampf '.\n\nWird keiner der Spielercharaktere innerhalb von 45 Sek. besiegt, werden beide mit ' Feigheit ' belegt." }
entries[320662] = { ["name"] = "Niyas Werkzeuge: Kräuter", ["text"] = "Seelenbandefähigkeit\nEure Heilzauber und -fähigkeiten haben eine Chance, Niyas kräftigende Kräuter anzuwenden und das Tempo des Ziels 10 Sek. lang um 5% zu erhöhen.\n(Procchance: 30%, 10s Abklingzeit)" }
