entries[320785] = { ["name"] = "Überwältigende Macht", ["text"] = "100 Meter Reichweite\nSofort\nMillhaus beschwört einen Machtkristall, der in Richtung von Millhaus kanalisiert und je nachdem, wer zuerst getroffen wird, entweder Spielercharaktere oder Millhaus beeinflusst.\n\n'Überwältigende Macht' fügt betroffenen Spielercharakteren alle 1 Sek. 96978 Arkanschaden zu und erhöht ihren verursachten Schaden um 2%. Dieser Effekt hält 3 Sek. lang an und ist stapelbar.\n\nWenn Millhaus von 'Überwältigende Macht' betroffen ist, wird sein verursachter Schaden 3 Sek. lang um 4% erhöht und ' Überwältigende Kraft! ' ausgelöst. Dieser Effekt ist stapelbar." }
entries[320786] = { ["name"] = "Überwältigende Macht", ["text"] = "100 Meter Reichweite\nSofort\nMillhaus beschwört einen Machtkristall, der in Richtung von Millhaus kanalisiert und je nachdem, wer zuerst getroffen wird, entweder Spielercharaktere oder Millhaus beeinflusst.\n\n'Überwältigende Macht' fügt betroffenen Spielercharakteren alle 1 Sek. 96978 Arkanschaden zu und erhöht ihren verursachten Schaden um 2%. Dieser Effekt hält 3 Sek. lang an und ist stapelbar.\n\nWenn Millhaus von 'Überwältigende Macht' betroffen ist, wird sein verursachter Schaden 3 Sek. lang um 4% erhöht und ' Überwältigende Kraft! ' ausgelöst. Dieser Effekt ist stapelbar." }
