entries[320813] = { ["name"] = "Feuerzauberschutz", ["text"] = "5% von Grundmana\nSofort 30 sek. Abklingzeit\nHüllt Euch in einen Schild aus Feuer, der für 30 Sek. [Zaubermacht * 2 * (1 + Vielseitigkeit)] Feuerschaden absorbiert.\n\nEs kann immer nur ein Zauberschutz aktiv sein." }
