entries[320820] = { ["name"] = "Randlauerer", ["text"] = "Animabonus\nSofort\nErhöht Eure Bewegungsgeschwindigkeit in der Nähe einer Wand oder der Seite eines Korridors um 60%." }
entries[320821] = { ["name"] = "Abschuss", ["text"] = "40 Meter Reichweite\nSofort 1.5 sek. Abklingzeit\nSchleudert Euch hoch in die Luft und lässt Euch dann für kurze Zeit gleiten." }
entries[320822] = { ["name"] = "Letzter Handel", ["text"] = "40 Meter Reichweite\nWirken in 4 sek. 3 sek. Abklingzeit\nHeilt ein verbündetes Ziel um 80% seiner maximalen Gesundheit und verursacht dann 20 Sek. lang alle 1 Sek. Schattenschaden in Höhe von 4% der maximalen Gesundheit des Zaubernden." }
entries[320823] = { ["name"] = "Experimentelle Eichhörnchenbombe", ["text"] = "Wirken in 1.5 sek.\nDie Eichhörnchenbombe lädt sich auf und explodiert dann, wobei sie allen Spielercharakteren 8000683 Feuerschaden zufügt. Die Bombe kann entschärft oder zerstört werden, um die Explosion zu verhindern." }
