entries[320825] = { ["name"] = "Mechanisches Bombeneichhörnchen", ["text"] = "100 Meter Reichweite\nWirken in 2 sek.\nMehrere mechanische Bombeneichhörnchen werden aus der Bombe freigelassen, von denen jedes auf einen Spielercharakter zustürmt und dann explodiert. Die Explosion verursacht 8 Feuerschaden und zerstört das Eichhörnchen." }
