entries[320830] = { ["name"] = "Mechanisches Bombeneichhörnchen", ["text"] = "15 Meter Reichweite\nSofort\nMehrere mechanische Bombeneichhörnchen werden aus der Bombe freigelassen, von denen jedes auf einen Spielercharakter zustürmt und dann explodiert. Die Explosion verursacht 1818337 Feuerschaden und zerstört das Eichhörnchen." }
entries[320832] = { ["name"] = "Fahrzeug benutzen" }
entries[320834] = { ["name"] = "Versetzungsfalle", ["text"] = "100 Meter Reichweite\nSofort\nHändlerin Xy'exa erschafft eine Versetzungsfalle, die Spielercharakteren innerhalb eines Radius von 10 Metern 15 Arkanschaden zufügt und den auslösenden Spielercharakter 25 Meter in die Luft teleportiert." }
