entries[320838] = { ["name"] = "Anima überspannen", ["text"] = "Wirken in 2.5 sek. 12 sek. Abklingzeit\nIncreases the caster's attacking and casting speed by 30% for 12 Sek.." }
entries[320839] = { ["name"] = "Entkräften", ["text"] = "20 Meter Reichweite\nKanalisiert (Wirken in 0 sek.)\nDer Zaubernde kanalisiert einen Strahl nekrotischer Energie auf den Spielercharakter, der ihm bis zu 5 Sek. lang alle 1 Sek. 363667 Schattenschaden zufügt und dabei sein Tempo sowie seine Bewegungsgeschwindigkeit um 50% verringert." }
entries[320840] = { ["name"] = "Wildtier zähmen", ["text"] = "Sofort\nZähmt ein Wildtier, sodass es zu Eurem Begleiter wird. Wenn Ihr aus irgendeinem Grund die Aufmerksamkeit des Tieres verliert, schlägt die Zähmung fehl.\n\nIhr müsst Euren aktiven Begleiter freigeben und einen freien Platz im Menü 'Begleiter rufen' haben, bevor ein neues Wildtier gezähmt werden kann. Exotische Tiere können nur von Jägern mit Tierherrschaftsspezialisierung gezähmt werden." }
