entries[320842] = { ["name"] = "Begleiter rufen", ["text"] = "Sofort\nBeschwört Euer erstes Tier zu Euch." }
entries[320843] = { ["name"] = "Hauen", ["text"] = "Nahkampfreichweite\nSofort 2 sek. Abklingzeit\nSchlägt auf das Ziel ein und verursacht 3636674 körperlichen Schaden." }
