entries[320851] = { ["name"] = "Tier wiederbeleben", ["text"] = "Sofort\nBringt Euer totes Tier mit 100% seiner Grundgesundheit wieder ins Leben zurück." }
entries[320852] = { ["name"] = "'Wildtier zähmen' erlernen", ["text"] = "Kanalisiert (Wirken in 7 sek.)\nLehrt jemanden 'Wildtier zähmen'." }
entries[320853] = { ["name"] = "Schattentor", ["text"] = "Pakt-Fähigkeit\nSofort\nWindet Euch durch die Schatten, um am Zielort zu erscheinen." }
entries[320854] = { ["name"] = "Geleiteter Stoß", ["text"] = "8 Meter Reichweite\nWirken in 0.5 sek. 3 sek. Abklingzeit\nInflicts Physical damage to an enemy." }
