entries[320859] = { ["name"] = "Unheiliges Zerschmettern", ["text"] = "Wirken in 1 sek." }
entries[320860] = { ["name"] = "Animainfusion" }
entries[320861] = { ["name"] = "Essenz entziehen", ["text"] = "40 Meter Reichweite\nWirken in 2 sek. 2 sek. Abklingzeit\nEntzieht dem Gegner die Lebensessenz, fügt ihm 2424449 Arkanschaden zu und gewährt dem Zaubernden eine Anwendung von ' Essenzwoge '." }
entries[320862] = { ["name"] = "Essenzwoge", ["text"] = "Sofort\nMacht wogt im Körper des Zaubernden auf und erhöht den verursachten Schaden 8 Sek. lang um 25%." }
entries[320863] = { ["name"] = "Berührung des Todes", ["text"] = "Sofort\nIhr nutzt die größte Schwachstelle des gegnerischen Ziels aus und fügt ihm sofort Schaden in Höhe von 100% Eurer maximalen Gesundheit zu [ Verbesserte Berührung des Todes : wenn es sich um eine Kreatur handelt, die über weniger Gesundheit verfügt als Ihr / .\n\nKann nur gegen Kreaturen eingesetzt werden, die weniger Gesundheit haben als Ihr.] [ Fügt Spielercharakteren sowie stärkeren Kreaturen mit weniger als 15% Gesundheit Schaden in Höhe von 35% Eurer maximalen Gesundheit zu ] [ Berührung des Todes : Verringert den gestaffelten Schaden um 200% des verursachten Schadens ] [ Erzeugt 3 Chisphären, die jeweils 1 Chi erzeugen, wenn Ihr durch sie lauft ] [ Erhöht den körperlichen Schaden des Mönchs für 10 Sek. um 15% ]" }
entries[320866] = { ["name"] = "Überkopfschlitzer", ["text"] = "100 Energie 20 Meter Reichweite\nWirken in 1 sek.\nDie Waffe des Zaubernden trifft bis zu zwei Ziele vor ihm. Wenn nur ein Ziel getroffen wird, erleidet dieses eine Tiefe Wunde." }
entries[320868] = { ["name"] = "Schreckliches Wörterbuch", ["text"] = "Animabonus\nSofort\nEure Intelligenz wird für jeden unterschiedlichen Wortzauber, den Ihr einsetzt, 5 Min. lang um 10% erhöht." }
entries[320869] = { ["name"] = "Lichtberührte Überreste", ["text"] = "Animabonus\nSofort\nVerringert die Manakosten von 'Blitzheilung' um 30%." }
entries[320870] = { ["name"] = "Blitzechofokus", ["text"] = "Animabonus\nSofort\nDer Effekt von [ Heilig : 'Blitzheilung' /\n\nDisziplin, Schatten\n'Schattenheilung' ] wird nach 4 Sek. wiederholt und heilt um 50% des ursprünglichen Werts." }
entries[320871] = { ["name"] = "Eifer des Vandalen", ["text"] = "Animabonus\nSofort\nWenn Ihr ein zerstörbares Objekt in Torghast zerstört, wird Euer nächster Einsatz von [ Heilig : 'Heiliges Feuer' /\n\nDisziplin, Schatten\n'Gedankenschlag' ] um 3% verstärkt. Bis zu 40-mal stapelbar." }
entries[320872] = { ["name"] = "Blitzkiste", ["text"] = "Animabonus\nSofort\nPro 30 Sek., in denen Ihr 'Blitzheilung' nicht einsetzt, wird die Heilung Eures nächsten Einsatzes von 'Blitzheilung' um 100% erhöht. Dieser Effekt ist bis zu 6-mal stapelbar." }
entries[320873] = { ["name"] = "Sengende Laterne", ["text"] = "Animabonus\nSofort\nEuer Zauber 'Blitzheilung' belegt das Ziel mit 'Sengendes Leuchten', wodurch es 20 Sek. lang 50% des erlittenen Schadens als Heiligschaden auf Angreifer reflektiert." }
entries[320874] = { ["name"] = "Segen des gefallenen Priesters", ["text"] = "Animabonus\nSofort\nDisziplin\nWenn Ihr 'Gedankenschlag' einsetzt, wird der Schaden oder die Heilung Eures nächsten Einsatzes von 'Sühne' um 30% erhöht. Dieser Effekt ist stapelbar, aber die Dauer wird nicht zurückgesetzt.\n\nSchatten\nWenn Ihr 'Gedankenschlag' einsetzt, wird der Schaden oder die Heilung Eures nächsten Einsatzes von 'Verschlingende Seuche' um 30% erhöht. Dieser Effekt ist stapelbar, aber die Dauer wird nicht zurückgesetzt.\n\nHeilig\nWenn Ihr 'Heiliges Feuer' einsetzt, wird der Schaden oder die Heilung Eures nächsten Einsatzes von 'Segenswort: Züchtigung' um 60% erhöht. Dieser Effekt ist stapelbar, aber die Dauer wird nicht zurückgesetzt.\n(100ms Abklingzeit)" }
entries[320875] = { ["name"] = "Verzehrender Refrain", ["text"] = "Animabonus\nSofort\nDer regelmäßige Schaden von 'Heiliges Feuer' hält 4 Sek. länger an." }
entries[320876] = { ["name"] = "Trunk des heiligen Feuers", ["text"] = "Animabonus\nSofort\n'Heiliges Feuer' hat eine Chance von 50%, keine Abklingzeit auszulösen." }
entries[320877] = { ["name"] = "Mal des rechtschaffenen Schutzes", ["text"] = "Animabonus\nSofort\nWährend ein Gegner innerhalb von 10 Metern von Eurem Effekt 'Heiliges Feuer' betroffen ist, erleidet Ihr 35% weniger Schaden." }
entries[320878] = { ["name"] = "Heiliger Höllenstein", ["text"] = "Animabonus\nSofort\nWenn 'Heiliges Feuer' abläuft, springt es auf ein anderes Ziel in der Nähe über." }
entries[320879] = { ["name"] = "Ideenverschlinger", ["text"] = "Animabonus\nSofort\nKritische Treffer mit 'Gedankenschlag' gewähren [ Schatten : 20 Wahnsinn /\n\nDisziplin, Heilig\n1000 Mana ]" }
entries[320880] = { ["name"] = "Schmerzrad", ["text"] = "Animabonus\nSofort\nErhöht die Dauer von [ Läuterung des Bösen : 'Läuterung des Bösen' / 'Schattenwort: Schmerz'] um 3 Sek. und erhöht den Schaden des Zaubers um 25%." }
entries[320881] = { ["name"] = "Schattenbeute", ["text"] = "Animabonus\nSofort\nWenn 'Schattenwort: Schmerz' abläuft, werden alle Gruppenmitglieder innerhalb von 20 Metern um das betroffene Ziel um 10% ihrer maximalen Gesundheit geheilt." }
entries[320882] = { ["name"] = "Rotglühende Gedankenpikser", ["text"] = "Animabonus\nSofort\nDer Initialschaden von 'Schattenwort: Schmerz' trifft immer kritisch." }
entries[320883] = { ["name"] = "Rattenkadaversack", ["text"] = "Animabonus\nSofort\nDas Töten einer Schlundratte gewährt Euch eine zusätzliche Aufladung von 'Schattenwort: Tod'.\n\nDer Sack kann bis zu 28 tote Schlundratten fassen." }
entries[320884] = { ["name"] = "Impulsor", ["text"] = "Animabonus\nSofort\n[ Heiliges Feuer : 'Heiliges Feuer' / 'Gedankenschlag'] macht das Ziel benommen, was seine Bewegungsgeschwindigkeit und Trefferchance 1 Min. lang um 20% verringert.\n\nDieser Effekt wird durch nachfolgende Einsätze von 'Gedankenschlag' oder 'Heiliges Feuer' entfernt." }
entries[320885] = { ["name"] = "Modifizierter Impulsor", ["text"] = "Animabonus\nSofort\nDer Einsatz von [ Heiliges Feuer : 'Heiliges Feuer' / 'Gedankenschlag'] hebt den Effekt 'Geblendet' nicht mehr auf." }
entries[320886] = { ["name"] = "Katharstift", ["text"] = "Animabonus\nSofort\n20% Eures sämtlichen erlittenen Schadens wird im Katharstift gespeichert. Der Initialschaden Eures nächsten Einsatzes von 'Schattenwort: Schmerz' fügt Eurem Ziel den gespeicherten Schaden zu." }
entries[320887] = { ["name"] = "Schmerzbrechender Psalm", ["text"] = "Animabonus\nSofort\n'Schattenwort: Tod' verbraucht Euren Effekt [ Läuterung des Bösen : 'Läuterung des Bösen' / 'Schattenwort: Schmerz'] auf dem Ziel und fügt ihm den gesamten verbleibenden Schaden zu." }
entries[320888] = { ["name"] = "Gedankenexplodierer", ["text"] = "Animabonus\nSofort\nErhöht den Schaden von 'Gedankenschlag' um 500%, die Abklingzeit der Fähigkeit aber auch um 400%." }
entries[320889] = { ["name"] = "Tagebuch der nekrotischen Gedanken", ["text"] = "Animabonus\nSofort\n'Gedankenkontrolle' kann bei untoten Wesen verwendet werden." }
entries[320890] = { ["name"] = "Psychischer Taschendiebstahl", ["text"] = "Animabonus\nSofort\nDer Einsatz von 'Gedankenkontrolle' bei einem Gegner leert dessen Taschen und gewährt Euch ungefähr 15 Phantasma." }
entries[320891] = { ["name"] = "Gebot der Ansteckung", ["text"] = "Animabonus\nSofort\nDer Einsatz von 'Gedankenkontrolle' bei einer Schlundratte löst 'Schnelle Ansteckung' aus, wodurch alle Schlundratten innerhalb von 15 Metern 2 bis 5 weitere Schlundratten gebären." }
entries[320892] = { ["name"] = "Fäden des Strippenziehers", ["text"] = "Animabonus\nSofort\n'Gedankenkontrolle' hält 30 Sek. länger an und erhöht den Schaden des Ziels um 50%." }
entries[320893] = { ["name"] = "Räuchergefäß der Rohheit", ["text"] = "Animabonus\nSofort\nIhr fügt Kreaturen, die furchterfüllt, entsetzt, betäubt oder benommen sind, 35% mehr Schaden zu." }
entries[320894] = { ["name"] = "Animagriff" }
entries[320895] = { ["name"] = "Dicke Juteschärpe", ["text"] = "Animabonus\nSofort\n'Machtwort: Seelenstärke' erhöht die Ausdauer zusätzlich um 10%." }
entries[320896] = { ["name"] = "Verzauberter Schleier", ["text"] = "Animabonus\nSofort\n'Machtwort: Seelenstärke' verringert zusätzlich den erlittenen Magieschaden um 10%." }
entries[320897] = { ["name"] = "Warme Decke", ["text"] = "Animabonus\nSofort\nVon Eurem Effekt 'Machtwort: Seelenstärke' betroffene Spielercharaktere gewähren Gruppenmitgliedern innerhalb von 3 Metern zusätzlich 10% Ausdauer." }
entries[320898] = { ["name"] = "Schriftrolle des Suchers", ["text"] = "Animabonus\nSofort\nWenn Ihr ein Aschenes Phylakterium zerstört, wird der Schaden von 'Feuerball', 'Frostblitz' oder 'Arkanschlag' um 2% erhöht. Dieser Effekt ist bis zu 100-mal stapelbar." }
entries[320899] = { ["name"] = "Zauberstabschmierfett", ["text"] = "Animabonus\nSofort\nDie Zauberzeit von [ Arkan (Level 10) : 'Arkanschlag' / Feuer : 'Feuerball' / Frost : 'Frostblitz' ] wird um 0.3 Sek. verringert." }
entries[320900] = { ["name"] = "Linse des Pandämoniums", ["text"] = "Animabonus\nSofort\nErhöht den Schaden von 'Arkane Explosion', 'Flammenstoß' und 'Blizzard' um 15%." }
entries[320901] = { ["name"] = "Hut des huschenden Zauberers", ["text"] = "Animabonus\nSofort\nWenn Ihr eine Kreatur mit [ Arkan (Level 10) : 'Arkane Explosion' / Feuer : 'Flammenstoß' / Frost : 'Blizzard' ] tötet, wird Euer Tempo 15 Sek. lang um 10% erhöht. Bis zu 10-mal stapelbar." }
entries[320902] = { ["name"] = "Gravur des Bombardiers", ["text"] = "Animabonus\nSofort\nArkan\nWenn Ihr einem Gegner mit 'Arkane Explosion' Schaden zufügt, wird automatisch 'Prismatische Barriere' angewendet. Dieser Effekt kann nur einmal alle 20 Sek. auftreten.\n\nFrost\nWenn Ihr einem Gegner mit 'Blizzard' Schaden zufügt, wird automatisch 'Eisbarriere' angewendet. Dieser Effekt kann nur einmal alle 20 Sek. auftreten.\n\nFeuer\nWenn Ihr einem Gegner mit 'Flammenstoß' Schaden zufügt, wird automatisch 'Lodernde Barriere' angewendet. Dieser Effekt kann nur einmal alle 20 Sek. auftreten.\n(20s Abklingzeit)" }
entries[320903] = { ["name"] = "Einladung des Chaos", ["text"] = "Animabonus\nSofort\nEuer erster Einsatz von pro Stock verursacht zusätzlich 850% Schaden." }
entries[320904] = { ["name"] = "Manaschuppe", ["text"] = "Animabonus\nSofort\nEuer [ Arkan (Level 10) : Feuer- und Frost / Feuer : Arkan- und Frost / Frost : Arkan- und Feuer ]schaden wird um 100% erhöht." }
entries[320905] = { ["name"] = "Saphirprisma", ["text"] = "Animabonus\nSofort\n'Spiegelbild' beschwört 2 zusätzliche Kopien von Euch." }
entries[320906] = { ["name"] = "Schriftrolle der leuchtenden Explosion", ["text"] = "Animabonus\nSofort\nWenn Ihr einem Gegner mit 'Arkane Explosion' Schaden zufügt, erleidet er 10 Sek. lang aus allen Quellen 15% mehr Schaden." }
entries[320907] = { ["name"] = "Stark polierter Handspiegel", ["text"] = "Animabonus\nSofort\nEure Spiegelbilder werden intelligenter und erhalten Zugriff auf mehr Eurer Zauber und Fähigkeiten." }
entries[320908] = { ["name"] = "Eisseele des Zauberers", ["text"] = "Animabonus\nSofort\n'Eisblock' hat keine Abklingzeit.\nModifies Cooldown -240000:\nEisblock" }
entries[320909] = { ["name"] = "Unheimliche Lehren", ["text"] = "Animabonus\nSofort\nErhöht den Schaden von [ Arkan : 'Arkanbeschuss' um 25% ] [ Feuer : 'Pyroschlag' um 25% /\n\nFrost\n'Hagel' um 40% ]" }
entries[320910] = { ["name"] = "Konstellationsschild", ["text"] = "Animabonus\nSofort\nWenn Ihr einen gegnerischen Zauber unterbrecht, wird der von Euch erlittene Schaden 20 Sek. lang um 20% verringert." }
entries[320911] = { ["name"] = "Resolutes Medaillon", ["text"] = "Animabonus\nSofort\nDie Absorption Eurer Barrierenzauber wird um 70% erhöht." }
entries[320912] = { ["name"] = "Tundraphiole", ["text"] = "Animabonus\nSofort\nDie Abklingzeit von 'Frostnova' wird um 5 Sek. verringert." }
entries[320913] = { ["name"] = "Immerwarme Socken", ["text"] = "Animabonus\nSofort\n'Eisblock' heilt Euch während seiner Dauer um 60% Eurer maximalen Gesundheit und bedeckt Eure Füße nicht mehr, wodurch Ihr Euch bewegen könnt... wenn auch nur sehr langsam." }
entries[320914] = { ["name"] = "Stundenglas des Chronomanten", ["text"] = "Animabonus\nSofort\nWährend 'Zeitverschiebung' aktiv ist, erhaltet Ihr und Eure Spiegelbilder 100% des Effekts von 'Zeitkrümmung'. Nicht von 'Temporale Verzerrung' oder ähnlichen Effekten betroffen.\n(1s Abklingzeit)" }
entries[320915] = { ["name"] = "Grausiger Eiszapfen", ["text"] = "Animabonus\nSofort\n'Frostnova' wird nicht mehr durch Schaden unterbrochen." }
entries[320916] = { ["name"] = "Dreieiniger Schutz", ["text"] = "Animabonus\nSofort\nDas Wirken eines beliebigen Barrierenzaubers gewährt die Effekte von 'Lodernde Barriere', 'Eisbarriere' und 'Prismatische Barriere'.\n(15s Abklingzeit)" }
entries[320917] = { ["name"] = "Flaschentesserakt", ["text"] = "Animabonus\nSofort\nErhöht die maximale Dauer von 'Zeitverschiebung' um 5 Sek." }
entries[320919] = { ["name"] = "Echos von Elisande", ["text"] = "Animabonus\nSofort\n'Zeitkrümmung' beschleunigt auch das Verstreichen der Zeit um 30%." }
entries[320920] = { ["name"] = "Paradoxon des Zeitbrechers", ["text"] = "Animabonus\nSofort\n'Zeitkrümmung' hält 300% länger an, aber sämtliche betroffenen Spielercharaktere werden am Ende der Effektdauer für 8 Sek. in der Zeit eingefroren." }
entries[320921] = { ["name"] = "Runenstoffbandagen", ["text"] = "Animabonus\nSofort\nWenn Ihr beim Wirken von 'Arkanschlag', 'Feuerball' oder 'Frostblitz' unsichtbar seid, erhöht sich der Schaden des Effekts um 500%." }
entries[320922] = { ["name"] = "Gekritzel des verrückten Magiers", ["text"] = "Animabonus\nSofort\nZu Beginn jedes Stocks erhaltet Ihr eine Eingebung, die Euch eine Reihenfolge bestimmter Zauber vermittelt.\n\nWenn Ihr diese Zauber erfolgreich in der richtigen Reihenfolge wirkt, wird Eure Intelligenz um 5% erhöht." }
entries[320923] = { ["name"] = "Arkanpulsdetektor", ["text"] = "Animabonus\nSofort\nBeim Tod wirkt Ihr automatisch 'Unsichtbarkeit'. Dies verbirgt Euch vor dem Kerkermeister und verhindert, dass Euer Tod bemerkt wird.\n\nDieser Effekt wird dadurch verbraucht." }
entries[320924] = { ["name"] = "Faden des Raumwebers", ["text"] = "Animabonus\nSofort\nDie Abklingzeit von 'Blinzeln' wird um 3 Sek. verringert." }
entries[320925] = { ["name"] = "Dimensionsklinge", ["text"] = "Animabonus\nSofort\nWenn Ihr Euch mit 'Blinzeln' durch einen Gegner bewegt, wird die Abklingzeit von 'Blinzeln' abgeschlossen. Schlundratten werden dabei sofort getötet." }
entries[320926] = { ["name"] = "Kunst des Blinzelmagiers", ["text"] = "Animabonus\nSofort\n'Blinzeln' hat keine Abklingzeit mehr und kostet kein Mana, Eure Bewegungsgeschwindigkeit ist jedoch auf 3 Meter pro Sekunde beschränkt." }
entries[320927] = { ["name"] = "Trüber Diamant", ["text"] = "Animabonus\nSofort\n'Blinzeln' hinterlässt ein Spiegelbild, das 10 Sek. lang bestehen bleibt." }
entries[320928] = { ["name"] = "Chaotisches Bildnis", ["text"] = "Animabonus\nSofort\nWenn Ihr ein Aschenes Phylakterium zerstört, wird der Schaden Eures nächsten Einsatzes von um 20% erhöht. Dieser Effekt ist bis zu 100-mal stapelbar." }
entries[320929] = { ["name"] = "Verdammnisstein" }
entries[320930] = { ["name"] = "Finsterstimmensignet", ["text"] = "Animabonus\nSofort\n[ Gebrechen : 'Dunkelblick beschwören' / Dämonologie : 'Dämonischen Tyrannen beschwören' / Zerstörung : 'Höllenbestie beschwören' ] beschwört 1 zusätzlichen Dämon." }
entries[320931] = { ["name"] = "Antlitz des Vielfraßes", ["text"] = "Animabonus\nSofort\nDer Einsatz von [ Gebrechen : 'Unheilvolle Euphorie' / Dämonologie : 'Schreckenspirscher rufen' / Zerstörung : 'Chaosblitz' ] gewährt Euch sofort 5 Phantasma.\n(1s Abklingzeit)" }
entries[320932] = { ["name"] = "Mal der geliehenen Macht", ["text"] = "Animabonus\nSofort\nZerstörung\n'Chaosblitz' hat eine Chance von 15%, 2 Seelensplitter zurückzuerstatten.\n\nDämonologie\n'Schreckenspirscher rufen' hat eine Chance von 15%, 2 Seelensplitter zurückzuerstatten und die Abklingzeit der Fähigkeit abzuschließen.\n\nGebrechen\n'Unheilvolle Euphorie' hat eine Chance von 15%, 5 Seelensplitter zurückzuerstatten.\n(100ms Abklingzeit)" }
entries[320933] = { ["name"] = "Besudelungsschild", ["text"] = "Animabonus\nSofort\nfügt Eurem durch 'Seele entziehen' gewährten Schild 400% mehr Absorption hinzu." }
entries[320934] = { ["name"] = "Insigne des Dimensionsfürsten", ["text"] = "Animabonus\nSofort\nVerringert die Abklingzeit von [ Gebrechen : 'Dunkelblick beschwören' / Dämonologie : 'Dämonischen Tyrannen beschwören' / Zerstörung : 'Höllenbestie beschwören' / 'Höllenbestie beschwören' ] um 10%." }
entries[320935] = { ["name"] = "Herz von Endereth", ["text"] = "Animabonus\nSofort\nerhöht die Vielseitigkeit aller Spielercharaktere in der Nähe um 25%." }
entries[320936] = { ["name"] = "Seelenbuffet", ["text"] = "Animabonus\nSofort\nGebrechen\nDie Dauer Eurer Fähigkeit 'Dunkelblick beschwören' ist um 100% erhöht, aber sie hat eine Chance von 50%, bei der Beschwörung einen Eurer Seelenrückstände zu verbrauchen.\n\nWenn ein Seelenrückstand verbraucht wird, wird der Schaden des Dunkelblicks zusätzlich um 100% erhöht.\n\nDämonologie\nDie Dauer Eurer Fähigkeit 'Dämonischen Tyrannen beschwören' ist um 100% erhöht, aber sie hat eine Chance von 50%, bei der Beschwörung einen Eurer Seelenrückstände zu verbrauchen.\n\nWenn ein Seelenrückstand verbraucht wird, wird der Schaden des dämonischen Tyrannen zusätzlich um 100% erhöht.\n\nZerstörung\nDie Dauer Eurer Fähigkeit 'Höllenbestie beschwören' ist um 100% erhöht, aber sie hat eine Chance von 50%, bei der Beschwörung einen Eurer Seelenrückstände zu verbrauchen.\n\nWenn ein Seelenrückstand verbraucht wird, wird der Schaden der Höllenbestie zusätzlich um 100% erhöht." }
entries[320937] = { ["name"] = "Detonationsfackel", ["text"] = "Animabonus\nSofort\nErhöht den Schaden von [ Gebrechen : 'Seelendieb' / 'Schattenblitz' / Dämonologie : 'Schattenblitz' und 'Dämonenblitz' / Zerstörung : 'Verbrennen' ] um 75%." }
entries[320938] = { ["name"] = "Infernospieße", ["text"] = "Animabonus\nSofort\nErhöht den Schaden von [ Gebrechen : 'Saat der Verderbnis' / Dämonologie : 'Implosion' / Zerstörung : 'Feuerregen' ] um 75%." }
entries[320939] = { ["name"] = "Zersetzende Phiole", ["text"] = "Animabonus\nSofort\n[ Dämonologie : 'Verderbnis' wird zum Spontanzauber /\n\nGebrechen, Zerstörung\n'Verderbnis' ] verringert zusätzlich die Bewegungsgeschwindigkeit von Gegnern um 60% und verursacht 100% mehr Schaden." }
entries[320940] = { ["name"] = "Auge von Endereth", ["text"] = "Animabonus\nSofort\nErhöht den Schaden Eures nächsten Einsatzes von 'Verderbnis' für jede befreite Seele in Eurem Besitz um 10%, bis zu einem Maximum von 250%." }
entries[320941] = { ["name"] = "Seelenleerentasche", ["text"] = "Animabonus\nSofort\nKreaturen, die sterben, während sie mit 'Verderbnis' belegt sind, haben eine Chance von 5%, einen Seelenrückstand zu gewähren." }
entries[320942] = { ["name"] = "Würgende Ketten", ["text"] = "Animabonus\nSofort\nEure Zauber zur Beschwörung von Dämonen sind Spontanzauber.\nModifies Cast Time -100%:\nLeerwandler beschwören , Sayaad beschwören , Sukkubus beschwören , Teufelsjäger beschwören , Teufelswache beschwören , Wichtel beschwören" }
entries[320943] = { ["name"] = "Pakt der Robustheit", ["text"] = "Animabonus\n99 Meter Reichweite\nSofort\nEure beschworenen Primärdämonen haben 50% mehr Gesundheit und verursachen 50% mehr Schaden." }
